#!/usr/bin/env node

/**
 * sc4sap Setup Init Hook (SessionStart, matcher: "init")
 * Runs initial setup when a new sc4sap project is initialized.
 * Creates .sc4sap directory structure and default configuration.
 */

import { existsSync, mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { readStdin } from './lib/stdin.mjs';

async function main() {
  try {
    const input = await readStdin();
    let data = {};
    try { data = JSON.parse(input); } catch {}

    const directory = data.cwd || data.directory || process.cwd();

    // Create .sc4sap directory structure
    const dirs = [
      join(directory, '.sc4sap'),
      join(directory, '.sc4sap', 'state'),
      join(directory, '.sc4sap', 'skills'),
      join(directory, '.sc4sap', 'research'),
      join(directory, '.sc4sap', 'logs'),
    ];

    for (const dir of dirs) {
      if (!existsSync(dir)) {
        try { mkdirSync(dir, { recursive: true }); } catch {}
      }
    }

    // Create default notepad if it doesn't exist
    const notepadPath = join(directory, '.sc4sap', 'notepad.md');
    if (!existsSync(notepadPath)) {
      try {
        writeFileSync(notepadPath, `# SC4SAP Project Notepad

## Priority Context
<!-- High-priority context that survives compaction -->

## Working Memory
<!-- Transient notes from the current work session -->

## SAP Objects
<!-- Track SAP objects being worked on -->

## Transport Requests
<!-- Active transport requests -->
`, { mode: 0o600 });
      } catch {}
    }

    // Create default project memory if it doesn't exist
    const memoryPath = join(directory, '.sc4sap', 'project-memory.json');
    if (!existsSync(memoryPath)) {
      try {
        writeFileSync(memoryPath, JSON.stringify({
          techStack: { languages: ['ABAP'], frameworks: ['SAP'] },
          sapModules: [],
          userDirectives: [],
          customNotes: [],
          scannedAt: new Date().toISOString()
        }, null, 2), { mode: 0o600 });
      } catch {}
    }

    console.log(JSON.stringify({
      continue: true,
      hookSpecificOutput: {
        hookEventName: 'SessionStart',
        additionalContext: '[SC4SAP] Project initialized. .sc4sap directory structure created.'
      }
    }));
  } catch (error) {
    console.log(JSON.stringify({ continue: true, suppressOutput: true }));
  }
}

main();
=================== setup-maintenance
#!/usr/bin/env node

/**
 * sc4sap Setup Maintenance Hook (SessionStart, matcher: "maintenance")
 * Performs maintenance tasks: cleanup stale state, verify configs.
 */

import { existsSync, readFileSync, readdirSync, unlinkSync, statSync } from 'fs';
import { join } from 'path';
import { readStdin } from './lib/stdin.mjs';

const STALE_STATE_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days

async function main() {
  try {
    const input = await readStdin();
    let data = {};
    try { data = JSON.parse(input); } catch {}

    const directory = data.cwd || data.directory || process.cwd();
    const messages = [];

    // Clean up stale state files
    const stateDir = join(directory, '.sc4sap', 'state');
    if (existsSync(stateDir)) {
      try {
        const now = Date.now();
        const files = readdirSync(stateDir, { withFileTypes: true });
        let cleanedCount = 0;

        for (const file of files) {
          if (!file.isFile() || !file.name.endsWith('.json')) continue;

          const filePath = join(stateDir, file.name);
          try {
            const stat = statSync(filePath);
            const age = now - stat.mtimeMs;

            if (age > STALE_STATE_AGE_MS) {
              // Check if the state is inactive before removing
              const content = JSON.parse(readFileSync(filePath, 'utf-8'));
              if (!content.active) {
                unlinkSync(filePath);
                cleanedCount++;
              }
            }
          } catch {}
        }

        if (cleanedCount > 0) {
          messages.push(`Cleaned ${cleanedCount} stale state file(s).`);
        }
      } catch {}
    }

    // Verify plugin config integrity
    const pluginRoot = process.env.CLAUDE_PLUGIN_ROOT;
    if (pluginRoot) {
      const hooksPath = join(pluginRoot, 'hooks', 'hooks.json');
      if (!existsSync(hooksPath)) {
        messages.push('WARNING: hooks.json not found. Plugin hooks may not be active.');
      }

      const claudeMdPath = join(pluginRoot, 'CLAUDE.md');
      if (!existsSync(claudeMdPath)) {
        messages.push('WARNING: CLAUDE.md not found. SAP development rules may not be enforced.');
      }
    }

    const summary = messages.length > 0
      ? `[SC4SAP Maintenance]\n${messages.join('\n')}`
      : '[SC4SAP] Maintenance check complete. No issues found.';

    console.log(JSON.stringify({
      continue: true,
      hookSpecificOutput: {
        hookEventName: 'SessionStart',
        additionalContext: summary
      }
    }));
  } catch (error) {
    console.log(JSON.stringify({ continue: true, suppressOutput: true }));
  }
}

main();
